// th15_s2_w05 — TH15 stage 2: six GirlD01 each fire an aimed alternating-layer ring.
// Source st02.ecl.txt:
//   MainSub03  1011-1026  spawns 6 GirlD01 at 60-frame intervals (kept, all six)
//   GirlD01    482-505    movement + async attack; unknown569/anm/drop omitted
//   GirlD01_at 507-553    etOn loop (etAim mode 9); only EX record is ANIM(a=1)
// Difficulty mask drives layers / speed / repeat count / volley gap per rank.

const TIME_LIMIT: int = 2124;
const OPENING_BUFFER: int = 120;

// Source etSprite(0, 7, 4): TH15 type 7 -> modern slot 464 (base radius 4),
// color 4 (valid 0-15). See transcribe/th15/bullet-types.md; art is a documented reuse.
const TH15_RING_BALL2: int = 464;
const BULLET_COLOR: int = 4;
const RING_WAYS: int = 10; // etCount count = 10 for every rank

// GirlD01_at, one volley of the etAim mode-9 aimed alternating-layer ring.
// Source geometry: angle(i,q) = A + (-1)^q * (R(i) + H(M,q)), alpha = 0,
//   delta = 0.05235988 rad = 3deg, H(M,2j) = H(M,2j+1) = (j + 0.5) * delta,
//   R(i) = 2*pi*i / RING_WAYS. Layer-q speed = s0 + (s1-s0)*k/(M-1), k = q&~1.
// Each even/odd layer pair shares one speed and sits at A+H / A-H, so a single
// 2-layer ring with base +H and layer step -2H reproduces the pair (RING_WAYS x 2).
sub volley(s0: fx, s1: fx, layers: int) {
    var n_pairs: int = layers / 2;
    var j: int = 0;
    while j < n_pairs {
        var k: int = 2 * j;
        var sp: fx = s0;
        if layers > 1 {
            sp = s0 + (s1 - s0) * (k as fx) / ((layers - 1) as fx);
        }
        // 3deg = 546 BAM; H = (2j+1)*273 BAM; layer step = -2H = -(2j+1)*546.
        var h: int = (2 * j + 1) * 273;
        var rot: int = -((2 * j + 1) * 546);
        sh_reset(0);
        sh_sprite(0, TH15_RING_BALL2, BULLET_COLOR);
        sh_ring(0, 1);
        sh_aim(0, 1);
        sh_count(0, RING_WAYS, 2);
        sh_angle(0, h as angle, rot as angle);
        sh_speed(0, sp, 0fx);
        sh_fire(0);
        j = j + 1;
    }
}

async sub girl_attack() {
    // !E/!N/!H/!LO pushed values; defaults below are Lunatic.
    var rank: int = global(GVAR_RANK);
    var layers: int = 8;  // etCount [-1]: E2 N6 H8 L8
    var s0: fx = 2.9fx;   // etSpeed first arg [-1]: E1.6 N1.6 H2.5 L2.9
    var reps: int = 6;    // diffI($A, 2, 3, 4, 6)
    var gap: int = 60;    // wait([-1]): E120 N120 H90 L60
    if rank == 0 {
        layers = 2; s0 = 1.6fx; reps = 2; gap = 120;
    } else if rank == 1 {
        layers = 6; s0 = 1.6fx; reps = 3; gap = 120;
    } else if rank == 2 {
        layers = 8; s0 = 2.5fx; reps = 4; gap = 90;
    }
    var s1: fx = 1.6fx; // etSpeed literal second arg

    wait(60); // GirlD01_at: wait(60) before first etNew/etOn

    // while($A--) { etOn; wait(gap); }  — fires reps volleys, gap after each.
    var n: int = reps;
    while n > 0 {
        volley(s0, s1, layers);
        wait(gap);
        n = n - 1;
    }
}

async sub girl_main() {
    set_invuln(65535);
    set_hurtbox(16fx); // setHurtbox(32,32): circular radius = 32*0.5
    set_hitbox(12fx);  // setHitbox(24,24): circular radius = 24*0.5

    // GirlD01: moveVel(pi/2, 3.0) then moveVelTime(80, mode1, pi/2, 0.0).
    move_vel(0, 90deg, 3fx, EASE_LINEAR);
    move_vel(80, 90deg, 0fx, EASE_QUAD_IN);

    spawn girl_attack(); // @GirlD01_at() async

    wait(80);
    move_speed(120, 0.6fx, EASE_QUAD_IN); // moveSpeedTime(120, mode1, 0.6)
    wait(60);
    // GirlD01_440/_420: infinite wait(1000) idle loop; enemy never deletes.
    loop { wait(1000); }
}

// MainSub03: enmCreate relative to STAGE (0,0) == these world coordinates.
async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(-32fx, -24fx, 1400, 0, 1000, 0, girl_main);
    wait(60);
    _ = spawn_enemy(-96fx, -24fx, 1400, 0, 1000, 0, girl_main);
    wait(60);
    _ = spawn_enemy(-144fx, -24fx, 1400, 0, 1000, 0, girl_main);
    wait(60);
    _ = spawn_enemy(32fx, -24fx, 1400, 0, 1000, 0, girl_main);
    wait(60);
    _ = spawn_enemy(96fx, -24fx, 1400, 0, 1000, 0, girl_main);
    wait(60);
    _ = spawn_enemy(144fx, -24fx, 1400, 0, 1000, 0, girl_main);
    wait(60);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
